<?php\n\nnamespace App\View\Components;\n\nuse Illuminate\View\Component;\nuse Illuminate\Database\Eloquent\Model;\n\nclass SeoHead extends Component\n{\n    public $model;\n    public $meta; // For manually passed meta tags\n\n    /**\n     * Create a new component instance.\n     *\n     * @param Model|null $model\n     * @param array $meta\n     */\n    public function __construct(Model $model = null, array $meta = [])\n    {\n        $this->model = $model;\n        $this->meta = $meta;\n    }\n\n    /**\n     * Get the view / contents that represent the component.\n     *\n     * @return \Illuminate\Contracts\View\View|\Closure|string\n     */\n    public function render()\n    {\n        // Initialize meta properties\n        $seo = (object) [\n            'title' => config('seo.default_title'),\n            'description' => config('seo.default_description'),\n            'keywords' => config('seo.default_keywords'),\n            'canonical_url' => url()->current(),\n            'robots' => config('seo.default_robots'),\n            'og_title' => config('seo.default_title'),\n            'og_description' => config('seo.default_description'),\n            'og_image' => config('seo.default_image'),\n            'og_type' => config('seo.default_og_type'),\n            'og_url' => url()->current(),\n            'twitter_card' => config('seo.default_twitter_card'),\n            'twitter_site' => config('seo.default_twitter_site'),\n            'twitter_creator' => null, // Usually dynamic per author\n            'twitter_title' => config('seo.default_title'),\n            'twitter_description' => config('seo.default_description'),\n            'twitter_image' => config('seo.default_image'),\n        ];\n\n        // Override with model's meta tags if available\n        if ($this->model && in_array('App\\Traits\\HasMetaTags', class_uses($this->model))) {\n            $seo->title = $this->model->getSeoTitle();\n            $seo->description = $this->model->getSeoDescription();\n            $seo->keywords = $this->model->getSeoKeywords(); \n            $seo->canonical_url = $this->model->getSeoCanonicalUrl();\n            $seo->robots = $this->model->getSeoRobots();\n\n            // Open Graph\n            $metaTag = $this->model->metaTag;\n            $seo->og_title = $metaTag->og_title ?? $seo->title;\n            $seo->og_description = $metaTag->og_description ?? $seo->description;\n            $seo->og_image = $this->model->getSeoImage() ?? $seo->og_image; // Use getSeoImage for fallback\n            $seo->og_type = $metaTag->og_type ?? $seo->og_type;\n            $seo->og_url = $metaTag->og_url ?? $seo->canonical_url;\n\n            // Twitter Cards\n            $seo->twitter_card = $metaTag->twitter_card ?? $seo->twitter_card;\n            $seo->twitter_site = $metaTag->twitter_site ?? $seo->twitter_site;\n            $seo->twitter_creator = $metaTag->twitter_creator ?? $seo->twitter_creator;\n            $seo->twitter_title = $metaTag->twitter_title ?? $seo->og_title; // Often same as OG title\n            $seo->twitter_description = $metaTag->twitter_description ?? $seo->og_description; // Often same as OG description\n            $seo->twitter_image = $this->model->getSeoImage() ?? $seo->twitter_image; // Use getSeoImage for fallback\n        }\n\n        // Override with manually passed meta tags if available\n        foreach ($this->meta as $key => $value) {\n            if (property_exists($seo, $key)) {\n                $seo->$key = $value;\n            }\n        }\n\n        // Ensure canonical URL is absolute\n        $seo->canonical_url = filter_var($seo->canonical_url, FILTER_VALIDATE_URL) ? $seo->canonical_url : url($seo->canonical_url);\n        $seo->og_url = filter_var($seo->og_url, FILTER_VALIDATE_URL) ? $seo->og_url : url($seo->og_url);\n\n\n        return view('components.seo-head', compact('seo'));\n    }\n}\n